(() => {
 'use strict';
 const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)], num=n=>new Intl.NumberFormat('ar-EG').format(n);
 const keys=Object.keys(courses), total=keys.reduce((n,k)=>n+courses[k].lessons.length,0);
 const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}};
 const saved=read('wm-completed',[]), completed=new Set(Array.isArray(saved)?saved.filter(x=>typeof x==='string'):[]);
 let current=null, toastTimer,cleanup=()=>{};
 function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}}
 function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
 function closeMenu(){$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').innerHTML=siteIcon('menu');}
 const badge=c=>`<span class="course-badge ${c.color}"><bdi dir="ltr">${c.name}</bdi></span>`;
 const crumbs=arr=>`<nav class="breadcrumbs" aria-label="مسار الصفحة"><a href="#home">الرئيسية</a>${arr.map(([text,url])=>`<span>/</span>${url?`<a href="${url}">${esc(text)}</a>`:`<span aria-current="page">${esc(text)}</span>`}`).join('')}</nav>`;
 const courseCard=(c,mode='learn')=>`<article class="course-card ${c.color}"><div class="course-card-top"><span class="track-number">${c.tag}</span><span class="course-symbol" dir="ltr">${siteIcon(c.id)}</span></div><h3 dir="ltr">${c.name}</h3><h4>${c.label}</h4><p>${c.desc}</p><div class="course-meta"><span>${num(c.lessons.length)} دروس مرتبة</span><span>من الصفر</span></div><div class="course-actions"><a class="btn primary" href="#course/${c.id}${mode==='practice'?'/practice':''}">${mode==='practice'?'الأسئلة والتمارين':'دروس الشرح'} ←</a><a class="text-link" href="#course/${c.id}${mode==='practice'?'':'/practice'}">${mode==='practice'?'دروس الشرح':'الأسئلة والتمارين'} ↗</a></div></article>`;
 function home(){return `<div class="page-wrap calm-home"><section class="calm-hero"><div class="calm-hero-copy"><span class="eyebrow">تعلّم الفرونت إند، خطوة بخطوة</span><h1>اتعلّم الفرونت إند.<br><em>خطوة بخطوة.</em></h1><p>شرح بسيط، أمثلة واضحة ورسومات توضّح الفكرة.<br>اختار اللغة، اقرا الدرس، وبعدها جرّب الأسئلة والتمارين.</p><a class="btn primary" href="#course/html">ابدأ من HTML ←</a><span class="home-byline">إعداد <bdi dir="ltr">Mohamed Hassany</bdi></span></div><div class="calm-hero-art"><img src="assets/web-studio.svg" width="580" height="430" alt="نافذة موقع مائلة حواليها بطاقات HTML وCSS وJavaScript وReact" fetchpriority="high" decoding="async"></div></section><section class="home-section" id="languages"><div class="section-heading"><div><h2>هتتعلم إيه النهارده؟</h2><p>لو لسه بتبدأ، امشي بالترتيب من HTML لحد React.</p></div></div><div class="course-grid">${keys.map(k=>courseCard(courses[k])).join('')}</div></section><p class="calm-home-note">كل درس له شرح، وأسئلة وتمارين في صفحة لوحدها. خُد وقتك، وارجع لأي نقطة محتاج تراجعها.</p></div>`;}
 function tracks(practice=false){return `<div class="page-wrap">${crumbs([[practice?'الأسئلة والتمارين':'مسارات التعلّم']])}<header class="page-heading"><span class="eyebrow">${practice?'مساحة التطبيق':'المحتوى كله، بالترتيب'}</span><h1>${practice?'اختار مسار، وجرّب فهمك.':'٤ مسارات، أساس واحد قوي.'}</h1><p>${practice?'لكل درس أسئلة وتمارين مستقلة عن الشرح. اختار المادة، وبعدها الدرس اللي عايز تتدرّب عليه.':'ابدأ بـ HTML لو جديد على الويب، أو ادخل المسار المناسب لمستواك. كل لغة لها دروسها وصفحات تطبيقها.'}</p></header><div class="course-grid">${keys.map(k=>courseCard(courses[k],practice?'practice':'learn')).join('')}</div><div class="callout"><div class="callout-title">الساعتين وقت تعلّم وتطبيق</div><p>الوقت المقترح شامل قراءة الأمثلة وتجربتها وحل التمارين والمراجعة. الوقت الفعلي حسب سرعتك؛ القراءة لوحدها أقل من كده.</p></div></div>`;}
 function lessonRows(c,practice,query=''){const list=c.lessons.map((l,i)=>({l,i})).filter(({l})=>(l.title+' '+l.desc+' '+l.sections.map(s=>s.title).join(' ')).toLowerCase().includes(query.toLowerCase().trim()));return list.length?list.map(({l,i})=>`<article class="lesson-row"><span class="row-number">${String(i+1).padStart(2,'0')}</span><div class="row-content"><a class="row-title" href="#${practice?'practice':'learn'}/${c.id}/${i}">${esc(l.title)}</a><p>${esc(l.desc)}</p><div class="row-meta"><span>${num(l.sections.length)} موضوعات</span><span>${practice?`${num(l.quizzes.length)} أسئلة + ${num(l.exercises.length)} تطبيقات`:'جلسة حوالي ساعتين'}</span>${completed.has(`${c.id}:${i}`)?'<span class="done-label">✓ الشرح مكتمل</span>':''}</div></div><div class="row-actions"><a class="btn ${practice?'secondary':'primary'}" href="#${practice?'practice':'learn'}/${c.id}/${i}">${practice?'حل وطبّق':'اقرا الشرح'} ←</a><a class="text-link" href="#${practice?'learn':'practice'}/${c.id}/${i}">${practice?'شرح الدرس':'أسئلة وتمارين'} ↗</a></div></article>`).join(''):'<p class="empty">مفيش درس بالبحث ده. جرّب اسم موضوع تاني.</p>';}
 function coursePage(id,practice=false){const c=courses[id],count=c.lessons.filter((_,i)=>completed.has(`${id}:${i}`)).length;return `<div class="page-wrap">${crumbs([['المسارات','#tracks'],[c.name]])}<header class="course-hero ${c.color}"><div>${badge(c)}<h1>${practice?'الأسئلة والتمارين':'رحلتك مع'} <bdi dir="ltr">${c.name}</bdi></h1><p>${c.desc}</p><span class="prerequisite">قبل البداية: ${c.prerequisite}</span></div><div class="course-hero-art"><span dir="ltr">${siteIcon(c.id)}</span><small>${num(c.lessons.length)} دروس · حوالي ساعتين للجلسة</small></div></header><nav class="course-tabs" aria-label="أقسام المسار"><a href="#course/${id}" class="${practice?'':'active'}" ${practice?'':'aria-current="page"'}>${siteIcon("book")} دروس الشرح</a><a href="#course/${id}/practice" class="${practice?'active':''}" ${practice?'aria-current="page"':''}>${siteIcon("pencil")} الأسئلة والتمارين</a><span>✓ ${num(count)} من ${num(c.lessons.length)} دروس مكتملة</span></nav><div class="section-heading course-list-heading"><div><h2>${practice?'اختار الدرس اللي هتتدرّب عليه.':'درس وراء درس، الصورة بتكمل.'}</h2><p>${practice?'الأسئلة والحلول هنا؛ صفحة الشرح ليها رابط منفصل.':'شرح حسب الموضوع، مع صفحة تطبيق منفصلة لكل درس.'}</p></div><label class="search"><span>⌕</span><input type="search" id="course-search" aria-label="ابحث في دروس المسار" placeholder="دوّر على موضوع..." autocomplete="off"></label></div><div id="lesson-list" class="lesson-list">${lessonRows(c,practice)}</div><div class="source-note">المحتوى اتنظّم من ملفات الشرح المقدمة مع تبسيط وتوضيحات وتمارين. <a href="${c.reference}" target="_blank" rel="noopener">التوثيق الرسمي للتوسّع ↗</a></div></div>`;}
 function quizHTML(q,i){return `<section class="quiz" data-quiz="${i}"><span class="eyebrow">السؤال ${num(i+1)}</span><h3>${esc(q.q)}</h3><div class="quiz-options">${q.options.map((o,j)=>`<button class="quiz-option" data-choice="${j}" aria-pressed="false"><span>${String.fromCharCode(65+j)}</span>${esc(o)}</button>`).join('')}</div><p class="quiz-feedback" role="status" aria-live="polite"></p></section>`;}
 function exerciseHTML(t,i){return `<section class="assignment"><div class="assignment-title"><span>${siteIcon("pencil")}</span><div><span class="eyebrow">التطبيق ${num(i+1)}</span><h3>${esc(t.title)}</h3></div></div><p>${esc(t.text)}</p>${t.criteria?.length?`<div class="checklist"><h4>راجع شغلك:</h4>${t.criteria.map((criterion,j)=>`<label><input type="checkbox" data-check="${i}:${j}"><span>${esc(criterion)}</span></label>`).join('')}</div>`:''}<details class="solution"><summary>خلصت المحاولة؟ افتح الحل للمراجعة <span>＋</span></summary>${code(t.solution,t.file)}<p class="solution-note">ده نموذج للحل، مش الطريقة الوحيدة. قارن المنطق واشرح سبب كل خطوة.</p></details></section>`;}
 function lessonPage(id,index,practice=false){const c=courses[id],l=c.lessons[index],prefix=practice?'practice':'learn';const previous=index>0?`<a class="btn secondary" href="#${prefix}/${id}/${index-1}">→ الدرس السابق</a>`:'';const next=index<c.lessons.length-1?`<a class="btn secondary" href="#${prefix}/${id}/${index+1}">الدرس الجاي ←</a>`:`<a class="btn secondary" href="#course/${id}${practice?'/practice':''}">راجع المسار ←</a>`;const words=l.sections.map(s=>s.html.replace(/<[^>]*>/g,' ')).join(' ').split(/\s+/).length;return `<div class="page-wrap reading-page">${crumbs([[c.name,`#course/${id}`],[practice?'الأسئلة والتمارين':'دروس الشرح',`#course/${id}${practice?'/practice':''}`],[`الدرس ${num(index+1)}`]])}<header class="reading-heading"><div class="reading-label">${badge(c)}<span>الدرس ${num(index+1)} من ${num(c.lessons.length)} · ${practice?'أسئلة وتمارين':'شرح'}</span></div><h1>${esc(l.title)}</h1><p>${esc(l.desc)}</p><nav class="lesson-switch" aria-label="صفحات الدرس"><a class="${practice?'':'active'}" href="#learn/${id}/${index}" ${practice?'':'aria-current="page"'}>${siteIcon("book")} شرح الدرس</a><a class="${practice?'active':''}" href="#practice/${id}/${index}" ${practice?'aria-current="page"':''}>${siteIcon("pencil")} أسئلة وتمارين الدرس</a></nav></header><div class="reader-grid"><article class="article" id="lesson"><details class="lesson-outline"><summary>محتويات ${practice?'صفحة التطبيق':'الدرس'} <span>＋</span></summary><nav aria-label="فهرس الدرس">${practice?'<a href="#questions" data-scroll="questions">أسئلة الفهم</a><a href="#exercises" data-scroll="exercises">التطبيقات والحلول</a>':l.sections.map(s=>`<a href="#learn/${id}/${index}/${s.id}" data-scroll="${s.id}">${esc(s.title)}</a>`).join('')}</nav><button class="outline-print" id="print-page">طباعة / حفظ PDF</button></details>${practice?`<div class="practice-intro"><span>✦</span><p>حل من غير فتح الشرح الأول. لو وقفت، ارجع للقسم المرتبط بالسؤال وبعدين جرّب تاني. الحلول مغلقة لحد ما تختار تفتحها.</p></div><h2 id="questions">اختبر فهمك</h2>${l.quizzes.map(quizHTML).join('')}<h2 id="exercises">طبّق بإيدك</h2>${l.exercises.map(exerciseHTML).join('')}<div class="practice-score" role="status"></div><button class="btn secondary" id="reset-quiz">ابدأ الأسئلة من جديد ⟳</button>`:`<p class="reading-time">قراءة الشرح حوالي ${num(Math.max(8,Math.ceil(words/100)))} دقيقة؛ الجلسة مع التطبيق حوالي ساعتين.</p>${l.sections.map((s,i)=>`<section class="topic" aria-labelledby="${s.id}"><div class="topic-heading"><span>${String(i+1).padStart(2,'0')}</span><h2 id="${s.id}">${esc(s.title.replace(/^[٠-٩0-9]+[.]\s*/,''))}</h2></div>${s.html}${lessonVisual(id,index,s.id)}</section>`).join('')}<div class="practice-cta"><div><span class="eyebrow">الفكرة وضحت؟ ثبّتها بالتطبيق.</span><h3>الأسئلة والتمارين في صفحة مستقلة.</h3><p>نفس الدرس، بمساحة تركز فيها على الحل.</p></div><a class="btn primary" href="#practice/${id}/${index}">أسئلة وتمارين الدرس ←</a></div><button class="btn secondary" id="complete-lesson">${completed.has(`${id}:${index}`)?'✓ الشرح مكتمل — إلغاء العلامة':'✓ خلّصت قراءة وفهم الشرح'}</button>`}<div class="lesson-end">${previous}${next}</div><div class="source-note">للمراجعة: <a href="${c.reference}" target="_blank" rel="noopener">التوثيق الرسمي ↗</a>. التقدّم والإجابات محفوظة محليًا على الجهاز ده.</div></article></div></div>`;}
 function glossaryResults(query=''){const out=keys.map(k=>{const terms=courseGlossary[k].filter(t=>t.join(' ').toLowerCase().includes(query.toLowerCase().trim()));return terms.length?`<section class="glossary-section"><h2 dir="ltr">${courses[k].name}</h2><div class="glossary-grid">${terms.map(t=>`<article class="glossary-card"><h3>${esc(t[1])}<bdi dir="ltr">${esc(t[0])}</bdi></h3><p>${esc(t[2])}</p><a class="text-link" href="#course/${k}">افتح مسار ${courses[k].name} ←</a></article>`).join('')}</div></section>`:'';}).join('');return out||'<p class="empty">مفيش مصطلح مطابق. جرّب كتابة مختلفة.</p>';}
 function glossaryPage(){return `<div class="page-wrap">${crumbs([['قاموس المصطلحات']])}<header class="page-heading"><span class="eyebrow">الاسم الإنجليزي، والمعنى بالعربي</span><h1>كل مصطلح، وليه حكاية.</h1><p>اقرأ المعنى وارجع للمسار لما تحتاج مثالًا كاملًا.</p></header><label class="search glossary-search"><span>⌕</span><input id="glossary-search" type="search" aria-label="ابحث في المصطلحات" placeholder="مصطلح عربي أو إنجليزي..."></label><div id="glossary-results">${glossaryResults()}</div></div>`;}
 function tidyBidi(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode()){const n=walker.currentNode;if(n.parentElement.closest('pre,code,bdi,[dir="ltr"],script,style,.course-symbol,.track-number,.brand-icon'))continue;if(/[A-Za-z]/.test(n.nodeValue))nodes.push(n);}nodes.forEach(n=>{const text=n.nodeValue,regex=/\([A-Za-z][A-Za-z0-9\s.,:/+&%_-]*\)|[A-Za-z][A-Za-z0-9_]*(?:[ .+&\/-][A-Za-z][A-Za-z0-9_]*)*/g,fragment=document.createDocumentFragment();let start=0;for(const match of text.matchAll(regex)){fragment.append(text.slice(start,match.index));const bdi=document.createElement('bdi');bdi.dir='ltr';bdi.className='en';bdi.textContent=match[0];fragment.append(bdi);start=match.index+match[0].length;}fragment.append(text.slice(start));n.replaceWith(fragment);});}
 function route(){cleanup();cleanup=()=>{};const hash=location.hash.slice(1)||'home';let m,mode='home',target=null;current=null;
  if((m=hash.match(/^course\/(html|css|js|react)(\/practice)?$/))){current={course:m[1],practice:!!m[2]};$('#content').innerHTML=coursePage(m[1],!!m[2]);mode=m[2]?'practice':'tracks';document.title=`${courses[m[1]].name} — Frontend Step`;}
  else if((m=hash.match(/^(learn|practice)\/(html|css|js|react)\/(\d+)(?:\/([a-z0-9-]+))?$/))&&courses[m[2]].lessons[Number(m[3])]){current={course:m[2],index:Number(m[3]),practice:m[1]==='practice'};target=m[4];$('#content').innerHTML=lessonPage(current.course,current.index,current.practice);mode=current.practice?'practice':'tracks';document.title=`${current.practice?'تطبيق: ':''}${courses[current.course].lessons[current.index].title} — Frontend Step`;if(!current.practice)save('wm-last',{course:current.course,index:current.index});}
  else if(hash==='tracks'||hash==='practice'){$('#content').innerHTML=tracks(hash==='practice');mode=hash;document.title=`${hash==='practice'?'الأسئلة والتمارين':'مسارات التعلّم'} — Frontend Step`;}
  else if(hash==='glossary'){$('#content').innerHTML=glossaryPage();mode='glossary';document.title='قاموس المصطلحات — Frontend Step';}
  else if(hash.startsWith('lesson-')){const old=Number(hash.slice(7).split('/')[0]);location.replace(`#learn/react/${Number.isInteger(old)&&old>=0&&old<8?old:0}`);return;}
  else{$('#content').innerHTML=home();document.title='Frontend Step — Mohamed Hassany';}
  $$('[data-nav]').forEach(a=>{const active=a.dataset.nav===mode;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});closeMenu();tidyBidi($('#content'));bind();window.scrollTo({top:0,behavior:'auto'});if(target)requestAnimationFrame(()=>document.getElementById(target)?.scrollIntoView({block:'start'}));
 }
 function bind(){
  $$('.copy-code').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText($('code',b.closest('.code-block')).textContent);b.textContent='اتنسخ ✓';toast('الكود اتنسخ. راجع اسم الملف قبل تجربته.');setTimeout(()=>{if(b.isConnected)b.textContent='نسخ الكود ⧉';},2000);}catch{toast('حدّد الكود وانسخه يدويًا؛ النسخ التلقائي مش متاح.');}});
  $$('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();a.closest('details')?.removeAttribute('open');document.getElementById(a.dataset.scroll)?.scrollIntoView({block:'start',behavior:'smooth'});});
  if($('#course-search'))$('#course-search').oninput=e=>{$('#lesson-list').innerHTML=lessonRows(courses[current.course],current.practice,e.target.value);tidyBidi($('#lesson-list'));};
  if($('#glossary-search'))$('#glossary-search').oninput=e=>{$('#glossary-results').innerHTML=glossaryResults(e.target.value);tidyBidi($('#glossary-results'));};
  if($('#complete-lesson'))$('#complete-lesson').onclick=()=>{const key=`${current.course}:${current.index}`;completed.has(key)?completed.delete(key):completed.add(key);const ok=save('wm-completed',[...completed]);$('#complete-lesson').textContent=completed.has(key)?'✓ الشرح مكتمل — إلغاء العلامة':'✓ خلّصت قراءة وفهم الشرح';toast(ok?'علامة تقدّمك اتحفظت ✓':'التخزين مش متاح؛ العلامة مؤقتة.');};
  if($('#print-page'))$('#print-page').onclick=()=>window.print();
  if(current?.index!==undefined&&current.practice)bindPractice();
  $$('[data-files]').forEach(ex=>{$('.file-list',ex).innerHTML=projectFiles.map(([name],i)=>`<button class="file-row" data-file="${i}">${esc(name)}</button>`).join('');$('.file-description',ex).textContent=projectFiles[3][1];$$('[data-file]',ex).forEach(b=>b.onclick=()=>{$$('[data-file]',ex).forEach(x=>x.classList.toggle('selected',x===b));$('.file-description',ex).textContent=projectFiles[Number(b.dataset.file)][1];tidyBidi($('.file-description',ex));});});
  const stops=[];$$('[data-demo]').forEach(d=>{const s=mountDemo(d);if(s)stops.push(s);});cleanup=()=>stops.forEach(f=>f());
 }
 function bindPractice(){const l=courses[current.course].lessons[current.index],key=`wm-answers-${current.course}-${current.index}`;let answers=read(key,{});if(!answers||typeof answers!=='object'||Array.isArray(answers))answers={};const render=()=>{$$('.quiz').forEach(card=>{const i=Number(card.dataset.quiz),q=l.quizzes[i],choice=answers[i];$$('.quiz-option',card).forEach(b=>{const selected=Number(b.dataset.choice)===choice;b.classList.toggle('correct',selected&&choice===q.answer);b.classList.toggle('wrong',selected&&choice!==q.answer);b.setAttribute('aria-pressed',String(selected));});$('.quiz-feedback',card).textContent=Number.isInteger(choice)?(choice===q.answer?'✓ صح. ':'جرّب تاني. ')+q.why:'';});const answered=l.quizzes.filter((_,i)=>Number.isInteger(answers[i])).length,correct=l.quizzes.filter((q,i)=>answers[i]===q.answer).length;$('.practice-score').textContent=`جاوبت ${num(answered)} من ${num(l.quizzes.length)} · إجابات صحيحة ${num(correct)} من ${num(l.quizzes.length)}`;tidyBidi($('#lesson'));};
  $$('.quiz-option').forEach(b=>b.onclick=()=>{answers[Number(b.closest('.quiz').dataset.quiz)]=Number(b.dataset.choice);save(key,answers);render();});$('#reset-quiz').onclick=()=>{answers={};save(key,answers);render();};render();
  const checksKey=`wm-checks-${current.course}-${current.index}`,checks=read(checksKey,{});$$('[data-check]').forEach(input=>{input.checked=checks?.[input.dataset.check]===true;input.onchange=()=>{const value=read(checksKey,{});save(checksKey,{...(value&&typeof value==='object'?value:{}),[input.dataset.check]:input.checked});};});
 }
 function mountDemo(d){const body=$('.practice-body',d),kind=d.dataset.demo;if(!body)return;const caption='<p class="demo-caption">معاينة للسلوك؛ كود React فوق وتتجرّبه في مشروعك.</p>';
  if(kind==='counter'){let n=0;body.innerHTML=`<p>جرّب زيادة العدد وتصفيره.</p><div class="demo-count" aria-live="polite">0</div><div class="demo-buttons"><button class="btn primary" data-add="1">+1</button><button class="btn secondary" data-add="3">+3</button><button class="btn secondary" data-reset>تصفير</button></div>${caption}`;$$('[data-add]',body).forEach(b=>b.onclick=()=>{$('.demo-count',body).textContent=n+=Number(b.dataset.add);});$('[data-reset]',body).onclick=()=>{$('.demo-count',body).textContent=n=0;};}
  if(kind==='name'||kind==='props'){body.innerHTML=`<label for="demo-${kind}">اكتب اسمك</label><input class="demo-input" id="demo-${kind}" placeholder="مثلًا: مريم" maxlength="60"><div class="preview-card"><h4>أهلًا يا <span data-name>صاحبنا</span></h4><p>خطوة صغيرة كل يوم.</p></div>${caption}`;$('input',body).oninput=e=>$('[data-name]',body).textContent=e.target.value.trim()||'صاحبنا';}
  if(kind==='tasks'){let tasks=[{id:1,title:'افهم State',done:false}],id=2;body.innerHTML=`<form class="task-add"><input class="demo-input" aria-label="اسم المهمة" placeholder="مهمة جديدة" maxlength="100"><button class="btn primary" type="submit">إضافة</button></form><p role="status" data-feedback></p><ul class="task-list"></ul>${caption}`;const paint=()=>{$('.task-list',body).innerHTML=tasks.map(t=>`<li><label><input type="checkbox" data-toggle="${t.id}" ${t.done?'checked':''}><span class="${t.done?'done':''}">${esc(t.title)}</span></label><button type="button" data-delete="${t.id}" aria-label="حذف ${esc(t.title)}">×</button></li>`).join('');tidyBidi($('.task-list',body));};$('form',body).onsubmit=e=>{e.preventDefault();const input=$('input',e.currentTarget),title=input.value.trim();if(!title){$('[data-feedback]',body).textContent='اكتب مهمة الأول.';return;}tasks=[...tasks,{id:id++,title,done:false}];input.value='';$('[data-feedback]',body).textContent='المهمة اتضافت.';paint();};$('.task-list',body).onclick=e=>{const b=e.target.closest('[data-delete]');if(b){tasks=tasks.filter(t=>t.id!==Number(b.dataset.delete));paint();}};$('.task-list',body).onchange=e=>{if(e.target.dataset.toggle){tasks=tasks.map(t=>t.id===Number(e.target.dataset.toggle)?{...t,done:e.target.checked}:t);paint();}};paint();}
  if(kind==='fetch'){let active=true,controller;body.innerHTML=`<p>بيانات تجريبية من JSONPlaceholder، محتاجة إنترنت.</p><button class="btn primary" data-load>تحميل البيانات ↗</button><div data-result role="status" aria-live="polite"></div>`;$('[data-load]',body).onclick=async()=>{controller?.abort();controller=new AbortController();const b=$('[data-load]',body);b.disabled=true;$('[data-result]',body).textContent='بنحمّل...';try{const res=await fetch('https://jsonplaceholder.typicode.com/posts?_limit=3',{signal:controller.signal});if(!res.ok)throw new Error('فشل');const data=await res.json();if(!Array.isArray(data))throw new Error('شكل غير متوقع');if(active)$('[data-result]',body).innerHTML=`<ul>${data.map(x=>`<li dir="auto">${esc(x.title)}</li>`).join('')}</ul>`;}catch(e){if(active&&e.name!=='AbortError')$('[data-result]',body).textContent='التحميل ماكملش. راجع الإنترنت وجرّب تاني.';}finally{if(active){b.disabled=false;b.textContent='تحميل من جديد ⟳';}}};return()=>{active=false;controller?.abort();};}
 }
 $('#menu-toggle').innerHTML=siteIcon('menu');
 $('#menu-toggle').onclick=()=>{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').innerHTML=siteIcon(open?'close':'menu');};
 $('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobile-nav').hidden){closeMenu();$('#menu-toggle').focus();}});
 const theme=read('wm-theme',read('rbm-theme','light'));document.body.classList.toggle('dark',theme==='dark');function labelTheme(){const dark=document.body.classList.contains('dark');$('#theme-toggle').innerHTML=siteIcon(dark?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',dark?'تفعيل الوضع الفاتح':'تفعيل الوضع الداكن');}labelTheme();$('#theme-toggle').onclick=()=>{document.body.classList.toggle('dark');save('wm-theme',document.body.classList.contains('dark')?'dark':'light');labelTheme();};
 window.matchMedia('(max-width: 1000px)').addEventListener('change',closeMenu);
 window.addEventListener('hashchange',route);route();
})();
